import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

const (
	mod = 1000000007
	eps = 1e-6
	pi  = 3.141592653589793
	inf = 1<<63 - 1
)

var sc *bufio.Scanner

func init() {
	sc = bufio.NewScanner(os.Stdin)
	sc.Split(bufio.ScanWords)
}

func nextInt() int {
	sc.Scan()
	i, _ := strconv.Atoi(sc.Text())
	return i
}

func nextLong() int64 {
	sc.Scan()
	i, _ := strconv.ParseInt(sc.Text(), 10, 64)
	return i
}

func nextFloat() float64 {
	sc.Scan()
	f, _ := strconv.ParseFloat(sc.Text(), 64)
	return f
}

func nextString() string {
	sc.Scan()
	return sc.Text()
}

func main() {
	t := nextInt()
	aa := make([]int, t)
	for i := 0; i < t; i++ {
		aa[i] = nextInt()
	}
	flag := 0
	a, b := 1, 2
	for i := 0; i < t; i++ {
		if aa[i] == a {
			b = 6 - (a + b)
		} else if aa[i] == b {
			a = 6 - (a + b)
		} else {
			flag = 1
			break
		}
	}
	if flag == 1 {
		fmt.Println("NO")
	} else {
		fmt.Println("YES")
	}
}

